import{_ as i}from"./chunks/v04-real-qwen2.5-3b-chat.Ch6sSIvZ.js";import{_ as a,o as s,c as d,a2 as e}from"./chunks/framework.CIOzaBgM.js";const F=JSON.parse('{"title":"第 0 章 本书怎么读","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/00-how-to-read.md","filePath":"chapters/00-how-to-read.md","lastUpdated":1791471399000}'),o={name:"chapters/00-how-to-read.md"};function r(l,t,n,h,p,c){return s(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="第-0-章-本书怎么读" tabindex="-1">第 0 章 本书怎么读 <a class="header-anchor" href="#第-0-章-本书怎么读" aria-label="Permalink to &quot;第 0 章 本书怎么读&quot;">​</a></h1><blockquote><p>本章目标：知道这本书讲什么、配套代码长什么样、需要准备什么环境，以及怎么对照 RAGFlow 源码阅读。</p></blockquote><h2 id="_0-1-这本书讲什么" tabindex="-1">0.1 这本书讲什么 <a class="header-anchor" href="#_0-1-这本书讲什么" aria-label="Permalink to &quot;0.1 这本书讲什么&quot;">​</a></h2><p>RAG（Retrieval-Augmented Generation，检索增强生成）的流程是：先从你自己的资料里找出相关片段，再让大模型基于这些片段作答。原理一句话就能讲完，可要真正做成一个可用的&quot;知识库&quot;，需要解决一长串工程问题：</p><ol><li><strong>入库</strong>：PDF、Word、Markdown、表格怎么变成干净的文本？文本切成多大的块？切在哪里？</li><li><strong>索引</strong>：每个块要存哪些字段，才能既支持关键词检索，又支持向量检索？</li><li><strong>检索</strong>：用户的一句话怎么变成查询？关键词分数和向量分数怎么合在一起？阈值设多少？</li><li><strong>生成</strong>：检索到的内容怎么塞进提示词？模型的回答怎么标注引用、让用户能点回原文？</li><li><strong>平台</strong>：多个用户、对外 API、后台任务的扩容与容错、数据源同步、部署。</li></ol><p><a href="https://github.com/infiniflow/ragflow" target="_blank" rel="noreferrer">RAGFlow</a> 是一个开源 RAG 引擎，对上面每个问题都给出了工程化的答案，而且答案写在代码里，我们可以逐行去读。本书的做法是：</p><ul><li><strong>读</strong>：从 RAGFlow 当前的 Go 实现（<code>internal/</code>）出发，沿着真实的调用链读源码，每个结论都附上 <code>path:line</code>；</li><li><strong>写</strong>：从零写一个 mini-ragflow，用同样的概念实现一个前后端都能跑的知识库系统。每个 Part 结束时升一个版本；</li><li><strong>对照</strong>：写完再回头和 RAGFlow 比较，找出真实存在的差距并修复，然后把修复的过程写进书里。</li></ul><p>读完之后，你应该能<strong>从零写出一个知识库 RAG 系统</strong>：上传文档 → 解析 → 切分 → 向量化 → 建索引 → 混合检索与重排 → 带引用的流式问答，并且能把它部署成多进程服务。</p><p>本书参照的版本是 <code>infiniflow/ragflow</code> main 分支，commit <code>11e00194b</code>（2026 年 10 月）。书中所有 <code>path:line</code> 都基于这个 commit 校验过。RAGFlow 正在从 Python 迁移到 Go，仓库里仍然留着一部分 Python 代码（<code>api/</code>、<code>rag/</code> 等），其中一些已经清空（例如 <code>rag/nlp/</code> 里只剩 <code>__pycache__</code>）。本书只读 Go 这一侧。少数地方 Go 代码仍在运行时读取 <code>rag/prompts/*.md</code> 里的提示词文件，书中会单独指出。</p><h2 id="_0-2-mini-ragflow-长什么样" tabindex="-1">0.2 mini-ragflow 长什么样 <a class="header-anchor" href="#_0-2-mini-ragflow-长什么样" aria-label="Permalink to &quot;0.2 mini-ragflow 长什么样&quot;">​</a></h2><p>配套代码放在 <code>code/mini-ragflow/</code>（GitHub：<code>luxiang0412/mini-ragflow</code>），共有六个版本：</p><table tabindex="0"><thead><tr><th>版本</th><th>能力</th><th>对应 Part</th></tr></thead><tbody><tr><td>v0.1</td><td>知识库与文档管理、异步解析任务、简单切分、前端文档表</td><td>Part II</td></tr><tr><td>v0.2</td><td>入库流水线 DSL、六种格式解析、五种切分策略、分词与向量化</td><td>Part III</td></tr><tr><td>v0.3</td><td>自研混合检索引擎、两阶段重排、检索测试页</td><td>Part IV</td></tr><tr><td>v0.4</td><td>带引用的流式知识库问答、会话、聊天 UI</td><td>Part V</td></tr><tr><td>v0.5</td><td>LLM 抽取关键词/问题/元数据、元数据过滤、RAPTOR</td><td>Part VI</td></tr><tr><td>v1.0</td><td>账号与 API Key、OpenAI/Dify/MCP 接口、多进程、数据源同步、Docker</td><td>Part VII</td></tr></tbody></table><p><img src="'+i+`" alt="图 0-1：v1.0 的聊天界面，回答中的蓝色数字是引用，鼠标悬停可以看到原文。"></p><p><em>图 0-1：mini-ragflow 的聊天界面。回答里的蓝色数字是引用，鼠标悬停会显示原文分块。（真实模型：bge-m3 + qwen2.5:3b）</em></p><p>技术栈选择&quot;和 RAGFlow 概念一致，复杂度降一档&quot;：</p><table tabindex="0"><thead><tr><th></th><th>RAGFlow</th><th>mini-ragflow</th></tr></thead><tbody><tr><td>后端</td><td>Go + gin + GORM</td><td>Go 标准库 <code>net/http</code></td></tr><tr><td>关系数据库</td><td>MySQL / PostgreSQL</td><td>SQLite（纯 Go 驱动，免 CGO）</td></tr><tr><td>对象存储</td><td>MinIO</td><td>本地目录</td></tr><tr><td>消息队列</td><td>NATS JetStream</td><td>SQLite 任务表 + 租约</td></tr><tr><td>检索引擎</td><td>Elasticsearch / Infinity / OceanBase…</td><td>自己写的内存倒排索引 + 向量扫描</td></tr><tr><td>文档理解</td><td>DeepDoc（ONNX 版面/OCR/表格模型）</td><td>文本层解析 + poppler <code>pdftotext</code></td></tr><tr><td>前端</td><td>React + Vite + TypeScript</td><td>React + Vite + TypeScript</td></tr><tr><td>模型</td><td>几十家厂商</td><td>mock + 任意 OpenAI 兼容接口</td></tr></tbody></table><p>被&quot;降档&quot;的地方，书里都会说明省掉了什么、为什么省、省掉的代价是什么。</p><h2 id="_0-3-环境准备" tabindex="-1">0.3 环境准备 <a class="header-anchor" href="#_0-3-环境准备" aria-label="Permalink to &quot;0.3 环境准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>版本</th></tr></thead><tbody><tr><td>Go</td><td>后端</td><td>1.26+</td></tr><tr><td>Node.js</td><td>前端</td><td>22+</td></tr><tr><td>poppler-utils</td><td>PDF 解析（<code>pdftotext</code>）</td><td>任意</td></tr><tr><td>Chrome</td><td>可选，跑 <code>web/e2e</code> 里的 UI 脚本</td><td>任意</td></tr><tr><td>Docker</td><td>可选，Part VII 部署</td><td>24+</td></tr><tr><td>Ollama</td><td>可选，接真实模型</td><td>任意</td></tr></tbody></table><p>不装 Ollama 也可以读完全书：mini-ragflow 自带一套确定性的 mock 模型，包括&quot;哈希 embedding&quot;和一个会流式输出、会写引用的&quot;假 LLM&quot;，全部测试都能离线跑通。书里凡是写着&quot;真实模型&quot;的输出，都是作者在本机用 Ollama 跑出来的（embedding 用 <code>bge-m3</code>，对话用 <code>qwen2.5:3b</code>）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/luxiang0412/mini-ragflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-ragflow</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-ragflow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 从第一个版本开始</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/mini-ragflow</span></span></code></pre></div><h2 id="_0-4-怎么读" tabindex="-1">0.4 怎么读 <a class="header-anchor" href="#_0-4-怎么读" aria-label="Permalink to &quot;0.4 怎么读&quot;">​</a></h2><ul><li>主线是 <strong>3 → 6 → 9 → 13 → 16</strong> 这几章（★ 越多越重要）。第 3 章把一份文档从上传到被引用的全过程走一遍，后面每一章都在拆这条链路上的某一段。</li><li>每章的结构都一样：<strong>问题与概念 → RAGFlow 怎么做 → 从零实现 → 运行与验证 → 练习 → 延伸阅读</strong>。</li><li>每个 Part 结尾有一个 Lab，带你把 mini-ragflow 升到下一个版本。用 <code>git diff v0.2 v0.3</code> 就能看到每一版改了什么。</li><li>&quot;踩坑记录&quot;里只写<strong>真实发生过</strong>的问题，都附有当时的报错或输出。靠自查发现、还没来得及触发的问题，书里会明确标注。</li></ul><p>本书对照阅读 RAGFlow 源码时用到的工具：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/infiniflow/ragflow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ragflow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 11e00194b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;func (s \\*RetrievalService) Retrieval&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internal/service/nlp/retrieval.go</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 按书中的 path:line 定位</span></span></code></pre></div><p>附录 A 是&quot;概念 → 源码路径&quot;的索引表，读源码迷路时可以去查。</p><h2 id="_0-5-练习" tabindex="-1">0.5 练习 <a class="header-anchor" href="#_0-5-练习" aria-label="Permalink to &quot;0.5 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：在本机跑通 <code>v0.1</code>，上传 <code>samples/</code> 里的三份文档，看它们被切成几块。</li><li><strong>扩展</strong>：列出你自己工作中最常检索的三类文档，想一想它们各自的&quot;结构&quot;是什么（标题、条款、表格、问答……）。读第 9 章时再回来对照。</li><li><strong>读源码</strong>：在 RAGFlow 的 <code>cmd/ragflow_server.go</code> 里找出它支持的所有 <code>--mode</code> 开关，猜猜每个模式负责什么。第 2 章会给出答案。</li></ol>`,28)])])}const m=a(o,[["render",r]]);export{F as __pageData,m as default};
